/** The critical results log — GET /api/v1/critical-results (who may call: holders of diagnostics.critical.view). */
export function listCritical(query?: { status?: "Open" | "Communicated" | "Acknowledged" | null; source?: "Lab" | "Imaging" | null; patient_id?: number | null; admission_id?: number | null; mine?: boolean; open_only?: boolean; date_from?: string | null; date_to?: string | null; limit?: number }): Promise<CriticalResultOut[]> {
  return api<CriticalResultOut[]>("GET", withQuery(`/critical-results`, query), undefined);
}

/** A critical result with who was told — GET /api/v1/critical-results/{critical_result_id} (who may call: holders of diagnostics.critical.view). */
export function getCritical(critical_result_id: number): Promise<CriticalResultDetailOut> {
  return api<CriticalResultDetailOut>("GET", `/critical-results/${critical_result_id}`, undefined);
}

/** Record who was told the critical result — POST /api/v1/critical-results/{critical_result_id}/communications (who may call: holders of diagnostics.critical.communicate). */
export function communicate(critical_result_id: number, body: CommunicationIn): Promise<CriticalResultDetailOut> {
  return api<CriticalResultDetailOut>("POST", `/critical-results/${critical_result_id}/communications`, body, { idempotent: true });
}

/** Diagnostic services work waiting — GET /api/v1/diagnostics/worklist (who may call: holders of diagnostics.critical.view or diagnostics.quality.view). */
export function diagnosticsWorklist(query?: { area?: "Lab" | "Imaging" | null; mine?: boolean }): Promise<DiagnosticsWorklistItemOut[]> {
  return api<DiagnosticsWorklistItemOut[]>("GET", withQuery(`/diagnostics/worklist`, query), undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
